import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for row in reader:
        if any(cell.strip() for cell in row):
            records.append([cell.strip() for cell in row])

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 5

    # Prefer the first plausible header-width record, allowing preamble lines
    # of other widths before it.
    header_index = next(
        (i for i, row in enumerate(records) if len(row) == expected_width),
        None,
    )

    if header_index is None:
        # Fall back to the first non-empty record when the file has no
        # record matching the expected width.
        header_index = 0

    columns = records[header_index]
    width = len(columns)

    def normalize(row: list[str]) -> list[str]:
        if len(row) < width:
            return row + [""] * (width - len(row))
        if len(row) > width:
            return row[:width - 1] + [";".join(row[width - 1:])]
        return row

    rows = [normalize(row) for row in records[header_index + 1:]]
    return {"columns": columns, "rows": rows}
